import sys, collections, heapq

def build_tree(n, edges):
    tree = [[] for _ in range(n)]
    for parent, *children in edges:
        for child in children:
            tree[parent - 1].append(child - 1)
    return tree

def dfs(root, vis):
    sequence = []
    stack = [root]
    while stack:
        u = stack.pop()
        if vis[u]:
            continue
        vis[u] = True
        sequence.append(u)
        for v in tree[u]:
            stack.append(v)
    return sequence

def query_distance(root, u, v):
    sequence = dfs(root, [False] * n)
    distances = [float('inf')] * n
    distances[root] = 0
    queue = [(0, root)]
    visited = set([root])
    while queue:
        dist, u = heapq.heappop(queue)
        if u == v:
            return dist
        v_list = tree[u]
        for k in reversed(range(len(tree[v])))[:min([1000000, len(tree[u])] - v_list.index(u), len(tree[u]))]:
            v = v_list[k]
            if v not in visited:
                visited.add(v)
                queue.append((dist + 1, v))
    return -1

def query_split(root, v, h):
    sequence = dfs(root, [False] * n)
    u = None
    for i in range(len(sequence) - 1, -1, -1):
        if sequence[i] == v:
            u = i
            break
    rem_poduct = 1
    for i in range(1, h + 1):
        rem_poduct *= u - i + 1
        rem_poduct -= rem_poduct % (10 ** 9 + 7)
    h -= 1
    for i in range(h, u, -1):
        rem_poduct *= sequence[i]
        rem_poduct %= (10 ** 9 + 7)
    return rem_poduct

def query_flatten(root, k):
    sequence = dfs(root, [False] * n)
    ans = -1
    for i in reversed(range(len(sequence) - 1)):
        if sequence[i] == root and len(sequence) - i - 1 >= pow(2, k, 10 ** 9 + 7):
            ans = sequence[i + 1]
            break
    return ans

def main():
    n, m = map(int, input().split())
    edges = [()]
    for _ in range(n):
        edges.extend(tuple(map(int, input().split())))
    tree = build_tree(n, edges)
