        stack.append(i)

    return startIndex

def can_be_stack_exterminable(n, arr):
    intersections = defaultdict(list)

    for i in range(n):
        for j in range(i, n):
            k = arr[j]
            intersections[k].append(i)

    intersections.update({(i, i): [] for i in range(n)})

    for i in intersections:
        nodes = intersections[i]
        start_idx = intersect_time(nodes)
        if start_idx not in intersections:
            intersections[start_idx] = nodes
        if not intersections[start_idx]:
            continue
        stack = say_can_be_stack_exterminable(intersections, start_idx, nodes)
        if stack:
            return True
    return False

def intersect_time(nodes):
    intersections = defaultdict(list)
    result = []
    for k in nodes[0]:
        stack = [k]
        for i in nodes:
            if stack and i[-1] < k:
                intersections[k].append(len(stack))
                stack = i
            else:
                stack.append(i)
        result += intersections[k]
    end = 0
    for i in result:
        if end < len(result) - i - 1:
            end += 1
        result[i] = end
    result.insert(0, 0)
    return result

def say_can_be_stack_exterminable(intersections, start_idx, nodes):
    fill_stack = defaultdict(list)
    result = 0

    left = 0
    for right in range(start_idx, len(intersections)):
        k = intersections[right]
        fill_stack.append([right])
        if start_idx < k < left + 1:
            continue
        diff_for_next = 0
        while left < right:
            d = fix_initializer(left, right, k, fill_stack, intersections)
            diff_for_next += d
            left += d
        result += diff_for_next
    return result if result else [1, len(nodes)]

def fix_initializer(left, right, k, fill_stack, intersections):
    left_init = right_init = 0
    l = 0
    for i in intersections[right]:
        if l < i + k:
            l = i
        left_init = fill_stack[left].pop()
    r = 0
    for i in intersections[left]:
        if l < i + k:
            l = i
        r = fill_stack[right].pop()
    for i in range(left_init, left):
        intersections[i].append(left)
    for i in range(r, right):
        intersections[i].append(right)
    intersections[left].append(right)
    return max(0, len(fill_stack[left]) + len(fill_stack[right]))
