def is_perfect_polygon(n):
    # Check if n is even or a multiple of 6
    return n % 2 == 0

def solve_triangle():
    n = int(input())   # Number of vertices

    # Check if n is less than 3, which trivially passes all vertex checks
    if n < 3:
        return "YES\nNone"

    count_apart = 0   # Count how many sides are apart and greater than the others
    count_same = 0    # Count how many sides are the same

    # Iterate over each side to count 'apart' and 'same' sides
    for i in range(n):
        for j in range(n):
            # Skip diagonal sides that will be considered apart or the same
            if i == j or i + j == n - 1:
                continue
            # Check if current side is apart or the same as the next
            if abs(i - j) > 1:
                count_apart += 1
            elif abs(i - j) == 1:
                count_same += 1

    # Check the conditions for an 'epic polygon'
    delta_sd = abs(math.floor(count_apart / 999))
    minp_side = count_apart - (2 * delta_sd) + count_same - delta_sd

    if is_perfect_polygon(n) and minp_side == n - 3:
        # If perfect polygon conditions and minp sides are met, print the response
        return "YES\n" + solve_random_triangle(2, n)

    return "NO"

