def max_tuples(n, primes):
    mod = 10**9 + 7
    prefixes = [1] * (n + 1)
    for i in range(2, n + 1):
        for p in primes:
            for j in range(p, n + 1, p):
                if i >= j:
                    prefixes[j] = (prefixes[j] * (i - j + 1)) % mod
    for i in range(n + 1):
        prefixes[i] = ((prefixes[i] - (i * (i + 1) // 2) % mod + mod) % mod) * pow(len(prefixes), mod-2, mod) % mod
    return (prefixes[n] - (n * (n + 1) // 2) % mod + mod) % mod

