from bisect import bisect_left

def f_lengthen(a, L, R):
    DP = []
    while L <= R:
        if L == R:
            DP.append(a[L-1])
            break
        i = (L + R) // 2 
        index_1 = bisect_left(DP, a[i-1])
        index_2 = bisect_left(DP, a[i])
        if index_2 - index_1 > 1:
            mid = (index_1 + index_2) // 2
            if DP[-1] > a[i-1] or len(DP) < mid:
                DP.append(a[i-1])
            else:
                DP[index_2 - 1] = a[i-1]
        elif index_1 < mid < index_2-1:
            DP[mid] = a[i-1]
        L, R = i+1, max(len(DP), R)
    return max(len(a) - DP.index(a[i-1]), len(DP))

