import numpy as np

def dp(stack_size, nums):
    stack = []
    dp = [0] * (stack_size + 1)
    dp[1] = [1 if x in stack else 0 for x in nums[:-1]]
    for i in range(1, stack_size):
        for j in range(stack_size - 1, -1, -1):
            if stack[j] >= stack_size:
                dp[i + 1] += dp[i]
            else:
                if nums[i + j] > nums[stack[j]]:
                    dp[i + 1] += dp[i + j - stack[j]]
                else:
                    break      # prevents overflow
    return dp[-1]

def fo(a):
    n = len(a)
    offset = 0
    a.sort()
    access = np.argsort(a)
    stack = []
    valid_total = []
    deque = []
    for i in range(n):
        stack.append(access[i])
        offset += a[access[i]]
        while len(stack) > len(deque):
            if stack[-1] < deque[-1]:
                stack.pop()
            else:
                deque.pop()
        if i >= 0 and a[access[i]] == a[stack[0]]:
            val = a[stack[0]]
            while len(stack) > 0 and stack[-1] == val:
                valid_total[-1] += 1
                stack.pop()
            deque.append(val)
        else:
            valid_total.append(0)
    fp = 0
    last_need = 0
    for i in range(1, len(valid_total) + 1, 1):
        if fp + i < len(valid_total):
            current_val = valid_total[fp + i]
            next_val = valid_total[(fp + i) + 1]
            if current_val == next_val:
                if fp + i + 1 < len(valid_total):
                    if dp[i + last_need] >= current_val:
                        fp += i
                    else:
                        last_need = i
    return fp
