def f(i, j, a, memo):
    if i > j:
        return 0
    if i == j:
        return a[i-1]
    if (i, j) in memo:
        return memo[(i, j)]
    memo[(i, j)] = min(f(i-1, j), f(i-1, j-1)) + a[j]
