def find_distance(u, v, tree):
    distances = defaultdict(list)
    tree[u].append(v)
    distances[1].append(u)

    stack = [tree[1][0]]
    visited = {1}

    while stack:
        parent = stack.pop()
        for child in tree[parent]:
            distances[child].append(parent)
            visited.add(child)
            if child not in visited:
                stack.append(child)

