# Fast exponentiation to compute (a**k % p) efficiently
def fast_exp(a, k, p):
    result = 1
    a = a % p
    while k:
        if k & 1: 
            result = (result * a) % p
        k >>= 1
        a = a * a % p
    return result

# Get all prime numbers up to max_prime
def get_primes(max_prime, memo=None):
    if memo is None:
        memo = {}
    if max_prime in memo:
        return memo[max_prime]
    current_primes = []
    root = int(max_prime**0.5)
    for i in range(2, root + 1):
        if max_prime % i == 0:
            current_primes.append(i)
            v = max_prime // i
            if v <= root:
                current_primes.append(v)
            while max_prime % i == 0:
                max_prime //= i
    if max_prime > 1:
        current_primes.append(max_prime)
    memo[max_prime] = current_primes
    return current_primes

