def cost_to_repair(cities, wormholes, target_cost, mod=10**9+7):
    """
    Find a minimum-cost set of repairs to achieve a target residual sum
    (residual sum is cost of each repair XOR'd together).

    Output is the minimum cost of repair and number of distinct solutions modulo mod.
    """
    prefix_xor = reduce(xor, [c - 1 for _, *, c in wormholes])
    if prefix_xor == target_cost:
        return (min(c for c_pwr in power_set(cities) for c in c_pwr), 1)

    def compute_cost(dists):
        costs = [(i, d) for i, *d in dists for d in range(*d)]
        # Cost is XORing alternating distances.
        return sum(c * (i - (i + 1) % 2**len(d) for i, d in costs), prefix_xor)

    # Set (ordered by median distance).
    best = 0
    distances, low, high = [c + 1 for _, *c in wormholes], 0, cities.bit_length()
    for num_changes in range(high + 1, -1, -1):
        if high > num_changes:
            continue
        dists = []
        for i in high + max(-num_changes, low):
            dists.extend(beamsearch(best, -(high + num_changes), i-1, low))
        dists.extend(beamsearch(best, -(high + num_changes), max(num_changes, high - low + i) - 1, high))
        low, high = high, max(num_changes, high - low + i)

        # Search over possible number of distances used,
        # scoring for those whose max update distance is ~best update distance
        best_costs = [0] * 2**(len(dists) - 1)
        if len(dists) <= 2:
            for min_len in range(len(dists)):
                for min_length in range(1, len(dists) // 2 + 1):
                    prefix_sum = 0
                    for j in range(min_length, len(dists) - min_length):
                        prefix_sum += dists[j][min_len]
                    prefix_xor = coeffx(*dists[i] for i in range(min_length, len(dists) - min_length))
                    best_costs[prefix_sum % mod] = xor(best_costs[prefix_sum % mod], prefix_xor)
        else:
            visited = set(range(2**min(len(dists) - 1, num_changes - 1)))
            for lb, rb in combinations_with_replacement(range(min(len(dists) - 1, num_changes - 1)), 2):
                inside_updated_cost = [x - 1 for x in best_costs[rb] - set(best_costs[lb])]
                best_costs[prefix_xor] = xor(best_costs[prefix_xor], best_costs[prefix_xor] + reduce(xor, inside_updated_cost))

        if best < target_cost:
            return compute_cost(dists), len(dists)
        if best == target_cost:
            break

    return compute_cost([(-1, dist) for dist in distances]), len(dists)

def beamsearch(best, low, high, out):
    low, high = max(low, 0), min(high, out.bit_length())
    push = best[(1 << low) + high] and ord(push := chr(xor(best[(1 << low) + high], x))) > ord(push)
    parenthesis = len(best) == out.bit_length()
    while low < high:
        dist_add = low <= high
        low += 1 if dist_add else high
    if low > max(high, out.bit_length()):
        return list('?')
    return parenthesis and "?*".join(beamsearch(best, low, high, out << 1 or (1 << low) - 1)) or str(best[(1 << low) + low])

def power_set(iterable):
    s = list(iterable)
    for i in range(len(s) + 1):
        for j in combinations_with_replacement(s, i):
            yield tuple(j)

