import math

class AdjustableConvexPolygon:
    def __init__(self, num_sides):
        self.num_sides = num_sides
        self.sides = [0] * num_sides
        self.vertices = []
        self.sides_taken = [False] * num_sides

    def adjust_sides(self, target_sides):
        """
        Adjust the sides to find the minimum possible side while ensuring all sides are unique
        """
        unique_sides = [self.num_sides] * len(self.sides)
        for side in range(len(self.sides)):
            if self.sides_taken[side]:
                continue
            unique_sides[side] = math.sqrt(sum((point[0] - self.sides[(side + i) % len(self.sides)][0])**2 + (point[1] - self.sides[(side + i) % len(self.sides)][1])**2 for i in range(self.num_sides)))
            if unique_sides[side] != target_sides:
                return False
        return True

    def check_position_on_lattice(self, x, y):
        for i in range(self.num_sides):
            dx = x - self.sides[(i + 2) % self.num_sides][0]
            dy = y - self.sides[(i + 2) % self.num_sides][1]
            if self.adjust_sides(math.sqrt(dx**2 + dy**2)):
                self.vertices.append((x, y))
                return True
        self.sides_taken.append(True)
        return False

    def is_possible(self):
        """
        Determine if it is possible to create a valid polygon based on lattice points and unique sides
        """
        return self.adjust_sides(self.num_sides)


