def can_labelling_satisfy_constraints(cities, roads):
    """ Check if a labeling is possible such that |xu - xv| <= 1 if and only if there is a road connecting u and v. """

    # Union-Find data structure to keep track of connected components
    uf = UnionFind(cities)
    sorted_roads = sorted(roads)

    # Traverse the roads and union cities that share a road
    for u, v in sorted_roads:
        uf.union(u, v)

    # Create a mapping of labels to their indices within the cities
    label_to_city = defaultdict(list)
    for city, label in enumerate(accumulate(uf.paranoid_iter())):
        label_to_city[label].append(city)

    # If there are multiple labels with one or more cities, return False
    for labels in label_to_city.values():
        if len(labels) > 1:
            return False

    return True

def union_find():
    pass

class UnionFind:
    def __init__(self, n):
        self.paranoid = [0] + list(range(1, n + 1))
        self.set_count = n

    def find(self, p):
        if p != self.paranoid[p]:
            self.paranoid[p] = self.find(self.paranoid[p])
        return self.paranoid[p]

    def union(self, rank, x, y):
        xroot = self.find(x)
        yroot = self.find(y)
        if rank[xroot] < rank[yroot]:
            self.paranoid[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            self.paranoid[yroot] = xroot
        else:
            self.paranoid[xroot] = yroot
            rank[yroot] += 1
        self.set_count -= 1

    def paranoid_iter(self):
        for root in range(1, self.set_count + 1):
            if self.find(root) != root:
                yield root

