def is_point_in_triangle(x1, y1, x2, y2, x3, y3, xi, yi):
    """Check if a point is inside the triangle formed by the given three points."""
    area0 = (y1 - y3) * (x2 - x0) - (x1 - x3) * (y2 - y0)
    area1 = (y2 - y3) * (x0 - x2) - (x2 - x3) * (y0 - y2)
    area2 = (y0 - y2) * (x1 - x0) - (x0 - x2) * (y1 - y0)
    return area0 * area1 * area2 in (0, 1)

def count_disjoint_triangles(points):
    """Count the number of distinct ways to choose two disjoint triangles."""
    triangles = set()
    for c in combinations(points, 3):
        flag = True
        for p in c:
            for sub_c in combinations(points - set([p]), 2):
                add_points = set()
                for sub_sub_c in combinations(sub_c, 3):
                    add_points = add_points.union(set([i for i in sub_sub_c]))
                for sub_sub_point in add_points:
                    if is_point_in_triangle(c[0][0], c[0][1], c[1][0], c[1][1], c[2][0], c[2][1], sub_sub_point[0], sub_sub_point[1]):
                        flag = False
                        break
                if flag:
                    triangles.add(tuple(sorted(list(c))))
                    break
    return len(triangles)

