    green_range = [(1, 1)]
    blue_range = [(1, 1)]

    for i in range(1, n):
        left, right = points[i]
        if right >= red_range[-1][0]:
            heappush(red_range, (right - left, left))
        elif right >= green_range[-1][0]:
            heappush(green_range, (right - left, left))
        elif right >= blue_range[-1][0]:
            heappush(blue_range, (right - left, left))
        elif right >= right:
            heappush(blue_range, (right - left, left))
        if points[i-1][1] == 'R':
            heappush(red_range, (1, points[i-1][0]))
        elif points[i-1][1] == 'G':
            heappush(green_range, (1, points[i-1][0]))
        elif points[i-1][1] == 'B':
            heappush(blue_range, (1, points[i-1][0]))

    min_cost = float('inf')
    while red_range and green_range and blue_range:
        r = heappop(red_range)[1]
        g = heappop(green_range)[1]
        b = heappop(blue_range)[1]

        r_idx = binary_search(r, red_range)
        g_idx = binary_search(g, green_range)
        b_idx = binary_search(b, blue_range)

        if r_idx > g_idx and r_idx > b_idx:
            continue
        elif g_idx > r_idx and g_idx > b_idx:
            min_cost = min(min_cost, 2 * r)
        elif b_idx > r_idx and b_idx > g_idx:
            min_cost = min(min_cost, 2 * b)
        else:
            min_cost = min(min_cost, r + g + b)

    return min_cost

def binary_search(p, heap):
    left, right = 0, len(heap)
    while left < right:
        mid = (left + right) // 2
        if heap[mid][1] < p:
            left = mid + 1
        else:
            right = mid
    return left

