import sys

class DirectionManager:
    def __init__(self):
        self.directed_channels = []
        self.undirected_channels = {}
        self.messages_transferred = 0

    def add_channel(self, channel):
        src, dest = channel.split()
        src, dest = int(src), int(dest)

        # Handle undirected channels
        if src not in self.undirected_channels:
            self.undirected_channels[src] = set()
        if dest not in self.undirected_channels:
            self.undirected_channels[dest] = set()

        self.undirected_channels[src].add(dest)
        self.undirected_channels[dest].add(src)

        # Add to directed channels list with bi-directional connections
        self.directed_channels.append((src, dest))
        self.directed_channels.append((dest, src))

        return self.directed_channels[-1]

    def transfer_message(self, src, dest):
        # Attempt to transfer messages. Return False if unsuccessful.
        path_exists = True

        # Check in each direction
        for src, dest in self.directed_channels:
            path_exists = self.check_path(src, dest)
            if not path_exists:
                break

        return path_exists

    def process_messages(self):
        while not self.messages_transferred == len(self.undirected_channels):
            src, dest = self.undirected_channels.popitem()  # Remove a random undirected channel
            self.transfer_message(src[0], dest[0]) if len(self.undirected_channels) else self.messages_transferred += 1

    def check_path(self, start, end):
        # Breadth-first search to find path
        visited = set()
        queue = [(start, "")]

        while queue:
            current_node, path = queue.pop(0)
            if current_node == end:
                return True

            if current_node in visited:
                continue
            visited.add(current_node)

            for neighbor in self.undirected_channels[current_node]:
                queue.append((neighbor, path + str(current_node) + "--" + str(neighbor)))

        return False

def solve(undirected_edges, directed_channels):
    manager = DirectionManager()
    for u, v in undirected_edges:
        if manager.add_channel(f"{u} {v}"):
            managed_channels = {u}
            managed_channels.add(v)

        receive_capacity = {v: u for u in managed_channels if len(undirected_edges[v]) > 1}
        manager.messages_transferred += 1
        if manager.transfer_message(u, v) and receive_capacity:
            cur_msg_source, cur_msg_destination = min(receive_capacity.items(), key=lambda k: k[1])  # Resolve receiver
            selection = cur_msg_source[0]
            remembered_msg_destination = cur_msg_source[1]
            command = (selected_channel for selected_channel in manager.directed_channels if remembered_msg_destination in selected_channel)[0]
