import math

def solve(x, y, vx, vy, n, m):
    # Check if the ball will hit a corner pocket
    if math.fabs(y) == m or math.fabs(x) == n:
        return (1 if math.fabs(x) == n else 0, m if math.fabs(y) == m else 0)

    # Initialize the distance to the bottom and right sides
    down_distance = 0
    right_distance = 0

    # Check if the ball will fall into one of the vertical sides
    if y > 0:
        down_distance = y
    else:
        up_distance = -y
        if math.fabs(x) < m + up_distance:
            down_distance = n
    if vy >= 0:
        down_distance += vy * down_distance // math.fabs(vy)

    # Check if the ball will fall into one of the horizontal sides
    if x > 0:
        right_distance = x
    else:
        left_distance = -x
        if math.fabs(y) < n - left_distance:
            right_distance = m
    if vx >= 0:
        right_distance += vx * right_distance // math.fabs(vx)

    # If the ball will land in the bottom-right corner
    if down_distance < right_distance:
        return (down_distance * 2 - 2, right_distance)

    # Compute the effective velocity vector
    effective_vx = vx
    effective_vy = vy

    # Check if the ball will fall into the top-left corner
    if y < 0:
        effective_vy = -vy - math.fabs(y)

    # Check if the ball will fall into the top-right corner
    if x < 0:
        effective_vx = -vx - math.fabs(x)

    # Check if the ball will fall into the bottom-right corner
    if down_distance < right_distance:
        return (down_distance * 2 - 2, right_distance)

    # If none of the pockets are hit, return -1
    return -1

# Example usage
