MOD = 998244353
two_power_n = [1]
for i in range(22):
    two_power_n.append(two_power_n[-1] * 2 % MOD)

def is_palindrome(s):
    return all(s[i] == s[-(i + 1)] for i in range(len(s) // 2))

def solve():
    s = input().strip()
    m = len(s)
    left = [1 for _ in range(1, m + 1)]
    for i in range(m - 2, -1, -1):
        left[i] = left[i + 1] * 2 % MOD
        if s[i] == '1':
            left[i] = (left[i] + two_power_n[m - 1 - i]) % MOD
    right = [left[-1]]
    for i in range(m - 1, -1, -1):
        right.append(right[-1] * 2 % MOD)
        if s[i] == '1':
            right[i] = (right[i] + two_power_n[m - 2 - i]) % MOD
    total = 0
    for p in range(1, left[0]):
        for q in range(p + 1, left[1]):
            diff = p - 1 - (2 * p - (m + 1) // 2 - 1)
            total = (total + left[0] * right[1] * diff % MOD * two_power_n[-1]) % MOD
    return total

print(solve())
