    return abs(p1 - p2)

def find_minimum_cost(n, points):
    colors = [p for _, color in points for p in color]
    costs = sorted(colors, key=lambda x: x)

    min_cost, end = 0, 0
    for color in costs:
        if color == 'B':
            break
        elif color == 'G':
            end = max(end, costs[min(min_cost, end)+1])
        else:
            min_cost = end if min_cost < end else min_cost
            end += 1

    return min_cost

